const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const ui={score:document.querySelector('#score'),best:document.querySelector('#best'),snacks:document.querySelector('#snacks'),combo:document.querySelector('#combo'),overlay:document.querySelector('#overlay'),title:document.querySelector('#title'),kicker:document.querySelector('#kicker'),message:document.querySelector('#message'),start:document.querySelector('#start'),announcement:document.querySelector('#announcement'),sound:document.querySelector('#sound')};
const notes=['PLEASE KEEP ALL BAD IDEAS STOWED','TURBULENCE IS JUST SKY CONFETTI','CAPTAIN HAS LOCATED THE VIBES','SNACK CART OPERATING AT MACH 2','DESTINATION: PROBABLY FINE'];
let W=360,H=560,dpr=1,state='ready',last=0,t=0,score=0,best=+(localStorage.getItem('cabin-chaos.best')||0),snacks=0,combo=1,plane,gates=[],particles=[],audio=true,ac;
ui.best.textContent=best;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
function reset(){score=snacks=0;combo=1;t=0;plane={x:W*.27,y:H*.48,vy:-Math.max(150,H*.28),rot:0};gates=[];particles=[];for(let i=0;i<4;i++)spawn(W+i*W*.52);sync()}
function spawn(x=W+80){const gap=Math.max(130,H*.25-score*.22),cy=110+Math.random()*(H-220),kind=Math.random()>.5?'cloud':'balloon';gates.push({x,cy,gap,w:58,passed:false,snack:Math.random()>.35,snackTaken:false,kind,phase:Math.random()*6})}
function sync(){ui.score.textContent=score;ui.snacks.textContent=snacks;ui.best.textContent=best;ui.combo.textContent=`COMBO READY · x${combo}`}
function beep(freq=440,dur=.05){if(!audio)return;ac??=new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.type='square';g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}
function boost(){if(state==='ready'||state==='over')start();if(state!=='playing')return;plane.vy=-Math.max(245,H*.48);for(let i=0;i<7;i++)particles.push({x:plane.x-21,y:plane.y+7,vx:-60-Math.random()*70,vy:(Math.random()-.5)*60,a:1});beep(520,.045)}
function start(){reset();state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function finish(){state='over';best=Math.max(best,score);localStorage.setItem('cabin-chaos.best',best);sync();ui.kicker.textContent='✦ FLIGHT DELAYED BY EXTREME VIBES';ui.title.innerHTML=`${score} gates!<br><em>${snacks} snacks.</em>`;ui.message.innerHTML='The passengers are confused but impressed.<br>One more highly unofficial flight?';ui.start.textContent='FLY AGAIN ↑';ui.overlay.classList.remove('hidden');beep(110,.2)}
function update(dt){t+=dt;plane.vy+=Math.max(720,H*1.25)*dt;plane.y+=plane.vy*dt;plane.rot=Math.max(-.35,Math.min(.75,plane.vy/520));const speed=Math.min(205,120+score*3);for(const g of gates){g.x-=speed*dt;g.cy+=Math.sin(t*1.2+g.phase)*8*dt;if(!g.passed&&g.x+g.w<plane.x){g.passed=true;score++;combo=Math.min(9,combo+1);ui.announcement.textContent='✦ '+notes[score%notes.length];beep(760+combo*35,.06);sync()}if(g.snack&&!g.snackTaken&&Math.hypot(g.x+g.w/2-plane.x,g.cy-plane.y)<30){g.snackTaken=true;snacks++;score+=combo;particles.push(...Array.from({length:14},()=>({x:plane.x,y:plane.y,vx:(Math.random()-.5)*150,vy:(Math.random()-.5)*150,a:1})));beep(1100,.08);sync()}const hitX=plane.x+22>g.x&&plane.x-22<g.x+g.w,hitY=plane.y-13<g.cy-g.gap/2||plane.y+13>g.cy+g.gap/2;if(hitX&&hitY)return finish()}gates=gates.filter(g=>g.x>-90);if(gates.at(-1).x<W*.6)spawn();for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.a-=dt*1.8}particles=particles.filter(p=>p.a>0);if(plane.y<45||plane.y>H-42)finish()}
function cloud(x,y,s=1){ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x,y,18*s,0,7);ctx.arc(x+22*s,y-9*s,26*s,0,7);ctx.arc(x+50*s,y,20*s,0,7);ctx.fill()}
function drawGate(g){ctx.save();const top=g.cy-g.gap/2,bottom=g.cy+g.gap/2;if(g.kind==='cloud'){for(let y=top-25;y>-30;y-=42)cloud(g.x,y,.65);for(let y=bottom+20;y<H+35;y+=42)cloud(g.x,y,.65)}else{ctx.fillStyle='#ff67c8';for(let y=top-32;y>-30;y-=58){ctx.beginPath();ctx.ellipse(g.x+29,y,24,31,0,0,7);ctx.fill();ctx.strokeStyle='#3f2764';ctx.beginPath();ctx.moveTo(g.x+29,y+30);ctx.lineTo(g.x+29,y+48);ctx.stroke()}for(let y=bottom+30;y<H+40;y+=58){ctx.beginPath();ctx.ellipse(g.x+29,y,24,31,0,0,7);ctx.fill()}}if(g.snack&&!g.snackTaken){ctx.translate(g.x+g.w/2,g.cy);ctx.rotate(Math.sin(t*4)*.15);ctx.fillStyle='#ffe45c';ctx.fillRect(-14,-11,28,22);ctx.fillStyle='#8a5c13';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('NUTS',0,3)}ctx.restore()}
function draw(){const grd=ctx.createLinearGradient(0,0,0,H);grd.addColorStop(0,'#70c7ff');grd.addColorStop(.72,'#bceaff');grd.addColorStop(1,'#ffe1ad');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.42;cloud((W-(t*17)% (W+150))-90,120,.8);cloud((W-(t*9)%(W+220))+30,250,.5);ctx.globalAlpha=1;for(const g of gates)drawGate(g);ctx.fillStyle='#314470';ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<W+30;x+=30)ctx.lineTo(x,H-25-(x%90));ctx.lineTo(W,H);ctx.fill();for(const p of particles){ctx.globalAlpha=p.a;ctx.fillStyle='#ffe45c';ctx.fillRect(p.x,p.y,5,3)}ctx.globalAlpha=1;ctx.save();ctx.translate(plane.x,plane.y);ctx.rotate(plane.rot);ctx.fillStyle='#f9f7ee';ctx.beginPath();ctx.moveTo(28,0);ctx.lineTo(-20,-12);ctx.lineTo(-34,-5);ctx.lineTo(-20,2);ctx.lineTo(-10,18);ctx.lineTo(3,18);ctx.lineTo(0,3);ctx.closePath();ctx.fill();ctx.fillStyle='#ff4d61';ctx.fillRect(-25,-11,9,13);ctx.fillStyle='#24385d';ctx.fillRect(10,-3,7,5);ctx.strokeStyle='#ff4d61';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-7,4);ctx.lineTo(13,10);ctx.stroke();ctx.restore()}
function loop(now){if(state!=='playing')return;const dt=Math.min(.03,(now-last)/1000);last=now;update(dt);draw();if(state==='playing')requestAnimationFrame(loop)}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();boost()});ui.start.onclick=()=>{if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}else start()};document.querySelector('#restart').onclick=start;ui.sound.onclick=()=>{audio=!audio;ui.sound.textContent=audio?'SOUND ON':'SOUND OFF'};addEventListener('keydown',e=>{if([' ','ArrowUp'].includes(e.key)){e.preventDefault();boost()}if(e.key.toLowerCase()==='p'){if(state==='playing'){state='paused';ui.kicker.textContent='FLIGHT PAUSED';ui.title.textContent='Snack break?';ui.message.textContent='Press P or tap below when you are ready.';ui.start.textContent='RESUME FLIGHT';ui.overlay.classList.remove('hidden')}else if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}}});addEventListener('resize',()=>{resize();if(state!=='playing'){reset();draw()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'){state='paused';ui.kicker.textContent='FLIGHT PAUSED';ui.title.textContent='Snack break?';ui.message.textContent='Tap below when you are ready.';ui.start.textContent='RESUME FLIGHT';ui.overlay.classList.remove('hidden')}});resize();reset();draw();
